BEGIN;SET LOCAL statement_timeout='20s';SET LOCAL lock_timeout='1s';
CREATE OR REPLACE FUNCTION public.r60_materialize_commercial_response_deadline() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_now timestamptz:=clock_timestamp();BEGIN IF NEW.commercial_stage='aguardando_resposta' THEN IF TG_OP='INSERT' OR OLD.commercial_stage IS DISTINCT FROM 'aguardando_resposta' THEN NEW.awaiting_response_since:=v_now;NEW.response_deadline_at:=v_now+interval '72 hours';END IF;ELSE NEW.awaiting_response_since:=NULL;NEW.response_deadline_at:=NULL;END IF;RETURN NEW;END $$;
DROP TRIGGER IF EXISTS r60_materialize_commercial_response_deadline_trg ON public.lead_commercial;CREATE TRIGGER r60_materialize_commercial_response_deadline_trg BEFORE INSERT OR UPDATE OF commercial_stage ON public.lead_commercial FOR EACH ROW EXECUTE FUNCTION public.r60_materialize_commercial_response_deadline();
CREATE OR REPLACE FUNCTION public.r60_refresh_response_deadline_from_sent() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NEW.leads_id IS NULL OR NEW.sents_sent_at IS NULL THEN RETURN NEW;END IF;IF TG_OP='UPDATE' AND OLD.sents_sent_at IS NOT DISTINCT FROM NEW.sents_sent_at AND OLD.leads_id IS NOT DISTINCT FROM NEW.leads_id THEN RETURN NEW;END IF;UPDATE public.lead_commercial SET awaiting_response_since=NEW.sents_sent_at,response_deadline_at=NEW.sents_sent_at+interval '72 hours' WHERE organizations_id=NEW.organizations_id AND leads_id=NEW.leads_id AND commercial_stage='aguardando_resposta';RETURN NEW;END $$;
DROP TRIGGER IF EXISTS r60_refresh_response_deadline_from_sent_trg ON public.sents;CREATE TRIGGER r60_refresh_response_deadline_from_sent_trg AFTER INSERT OR UPDATE OF sents_sent_at,leads_id ON public.sents FOR EACH ROW EXECUTE FUNCTION public.r60_refresh_response_deadline_from_sent();
CREATE OR REPLACE FUNCTION public.r60_refresh_response_deadline_from_message() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_event_at timestamptz;BEGIN IF NEW.leads_id IS NULL THEN RETURN NEW;END IF;IF NEW.direction='inbound' THEN IF TG_OP='INSERT' THEN UPDATE public.lead_commercial SET awaiting_response_since=NULL,response_deadline_at=NULL WHERE organizations_id=NEW.organizations_id AND leads_id=NEW.leads_id AND commercial_stage='aguardando_resposta';END IF;RETURN NEW;END IF;IF NEW.direction<>'outbound' OR NEW.message_status NOT IN('sent','delivered','read') THEN RETURN NEW;END IF;IF TG_OP='UPDATE' AND OLD.message_status IN('sent','delivered','read') THEN RETURN NEW;END IF;v_event_at:=coalesce(NEW.conversation_messages_created_at,clock_timestamp());UPDATE public.lead_commercial SET awaiting_response_since=v_event_at,response_deadline_at=v_event_at+interval '72 hours' WHERE organizations_id=NEW.organizations_id AND leads_id=NEW.leads_id AND commercial_stage='aguardando_resposta';RETURN NEW;END $$;
DROP TRIGGER IF EXISTS r60_refresh_response_deadline_from_message_trg ON public.conversation_messages;CREATE TRIGGER r60_refresh_response_deadline_from_message_trg AFTER INSERT OR UPDATE OF message_status ON public.conversation_messages FOR EACH ROW EXECUTE FUNCTION public.r60_refresh_response_deadline_from_message();REVOKE ALL ON FUNCTION public.r60_materialize_commercial_response_deadline() FROM PUBLIC;REVOKE ALL ON FUNCTION public.r60_refresh_response_deadline_from_sent() FROM PUBLIC;REVOKE ALL ON FUNCTION public.r60_refresh_response_deadline_from_message() FROM PUBLIC;COMMIT;
